@Composable
fun TaskScreen() {
    Column {
        LazyRow {
            items(categories) { category ->
                Card(
                    modifier = Modifier
                        .padding(8.dp)
                        .clickable(onClick = { /* Gérer le clic sur catégorie */ }),
                    elevation = 4.dp
                ) {
                    Text(
                        text = category.name,
                        modifier = Modifier.padding(16.dp),
                        style = MaterialTheme.typography.body2
                    )
                }
            }
        }

        LazyColumn(
            modifier = Modifier.fillMaxSize()
        ) {
            items(tasks) { task ->
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(8.dp)
                        .clickable(onClick = { /* Gérer le clic sur tâche */ }),
                    elevation = 2.dp
                ) {
                    Column(
                        modifier = Modifier.padding(16.dp)
                    ) {
                        Text(
                            text = task.title,
                            style = MaterialTheme.typography.body1
                        )
                        Text(
                            text = task.description,
                            style = MaterialTheme.typography.body2,
                            color = Color.Gray
                        )
                    }
                }
            }
        }
    }
}

